const providersInTimeline = useMemo(() => {
  if (!data) return [];
  const maxIiByProvider = new Map<string, number>();
  for (const m of data.models) {
    if (m.intelligenceIndex !== null && m.intelligenceIndex !== undefined) {
      const current = maxIiByProvider.get(m.provider) || 0;
      if (m.intelligenceIndex > current) {
        maxIiByProvider.set(m.provider, m.intelligenceIndex);
      }
    }
  }
  return Array.from(maxIiByProvider.entries())
    .sort((a, b) => b[1] - a[1]) // sort by max II descending
    .slice(0, 6)
    .map((entry) => entry[0]);
}, [data]);

// 3. Velocidad vs Ventana de Contexto (Scatter)
const contextSpeedData = useMemo(() => {
  if (!data) return [];
  return data.models
    .filter((m) => m.contextWindow != null && m.contextWindow > 0 && m.speedTps != null)
    .map((m) => ({
      x: Math.log10(m.contextWindow!),
      rawContext: m.contextWindow,
      y: m.speedTps,
      name: m.name,
      provider: m.provider,
      color: m.providerColor || "#5e6ad2",
    }));
}, [data]);

// 4. Open Weights vs Propietario (Barra Apilada por Proveedor)
const openWeightsData = useMemo(() => {
  if (!data) return [];
  const groups = new Map<string, { open: number; closed: number }>();
  for (const m of data.models) {
    if (!groups.has(m.provider)) groups.set(m.provider, { open: 0, closed: 0 });
    if (m.openWeights) {
      groups.get(m.provider)!.open++;
    } else {
      groups.get(m.provider)!.closed++;
    }
  }
  return Array.from(groups.entries())
    .map(([provider, counts]) => ({
      provider,
      open: counts.open,
      closed: counts.closed,
      total: counts.open + counts.closed,
    }))
    .sort((a, b) => b.total - a.total);
}, [data]);

// 5. Coding vs Agentic Index (Scatter)
const codingAgenticData = useMemo(() => {
  if (!data) return [];
  return data.models
    .filter((m) => m.codingIndex != null && m.agenticIndex != null)
    .map((m) => ({
      x: m.codingIndex,
      y: m.agenticIndex,
      name: m.name,
      provider: m.provider,
      color: m.providerColor || "#5e6ad2",
    }));
}, [data]);

// 6. Velocidad vs Precio (Scatter)
const efficiencyData = useMemo(() => {
  if (!data) return [];
  return data.models
    .filter((m) => m.priceInputUsd != null && m.priceInputUsd > 0 && m.speedTps != null)
    .map((m) => ({
      x: Math.log10(m.priceInputUsd!),
      rawPrice: m.priceInputUsd,
      y: m.speedTps,
      name: m.name,
      provider: m.provider,
      color: m.providerColor || "#5e6ad2",
    }));
}, [data]);

