function GerenteOverview() {
  const { data } = useEffectiveDashboardData();

  const targetStatIds = [
    "frontier-price-drop",
    "price-direction-yoy",
    "releases-12mo",
    "busiest-month",
    "open-vs-closed-price",
    "arena-current-streak",
  ];

  const benchlmStats = useMemo(() => {
    if (!data?.benchlmStats) return [];
    return targetStatIds
      .map((id) => data.benchlmStats!.find((s) => s.statId === id))
      .filter(Boolean);
  }, [data]);

  const modalitiesData = useMemo(() => {
    if (!data) return [];
    const counts: Record<string, number> = { text: 0, image: 0, video: 0, file: 0, audio: 0 };
    for (const m of data.models) {
      if (m.orInputModalities) {
        for (const mod of m.orInputModalities) {
          if (counts[mod] !== undefined) counts[mod]++;
        }
      }
    }
    return Object.entries(counts)
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count);
  }, [data]);

  return (
    <div className="space-y-6">
      <GerenteView />

      {/* 1. Panel de Estadísticas BenchLM */}
      <section>
        <div className="mb-3">
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">Estadísticas de Mercado (BenchLM)</h2>
          <p className="text-sm text-[var(--text-secondary)]">Métricas clave del estado actual de los LLMs</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {benchlmStats.map((stat) => (
            <Card key={stat!.statId} className="bg-[var(--bg-surface)] border-[var(--border-default)]">
              <CardHeader className="pb-2">
                <CardTitle className="text-xs font-semibold uppercase tracking-wider text-[var(--text-secondary)]">
                  {stat!.label}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-xl font-bold text-[var(--text-primary)] mb-1">
                  {stat!.value}
                </div>
                <p className="text-xs text-[var(--text-secondary)] line-clamp-2" title={stat!.sentence}>
                  {stat!.sentence}
                </p>
              </CardContent>
            </Card>
          ))}
        </div>
      </section>

      {/* 2. Modelos por Modalidad */}
      <section>
        <Card className="bg-[var(--bg-surface)] border-[var(--border-default)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base font-semibold tracking-tight">
              Modelos por Modalidad de Entrada
            </CardTitle>
            <CardDescription className="text-xs">
              Respuesta rápida a "¿Qué pueden hacer los modelos hoy?"
            </CardDescription>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300} debounce={50}>
              <BarChart
                data={modalitiesData}
                layout="vertical"
                margin={{ top: 10, right: 30, left: 20, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="var(--border-default)" />
                <XAxis type="number" axisLine={{ stroke: "var(--border-default)" }} tickLine={false} tick={{ fill: "var(--text-secondary)", fontSize: 11 }} />
                <YAxis dataKey="name" type="category" axisLine={{ stroke: "var(--border-default)" }} tickLine={false} tick={{ fill: "var(--text-secondary)", fontSize: 11, textTransform: "capitalize" }} width={60} />
                <RechartsTooltip
                  cursor={{ fill: "var(--bg-overlay)" }}
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0].payload;
                    return (
                      <div className="rounded-lg border border-[var(--border-strong)] bg-[var(--bg-elevated)] p-2.5 shadow-lg text-xs">
                        <div className="font-semibold text-[var(--text-primary)] capitalize">{d.name}</div>
                        <div className="text-[var(--text-secondary)] mt-0.5">
                          <span className="num text-[var(--text-primary)]">{d.count}</span> modelos
                        </div>
                      </div>
                    );
                  }}
                />
                <Bar dataKey="count" fill="var(--brand-primary)" radius={[0, 4, 4, 0]} barSize={24} isAnimationActive={false}>
                  <LabelList dataKey="count" position="right" style={{ fill: "var(--text-secondary)", fontSize: 11 }} className="num" />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

